create table public.sp_employers(owner_id uuid primary key references auth.users(id) on delete cascade,company_name text not null check(length(company_name) between 2 and 160),website text not null default '' check(length(website)<=250),company_context text not null default '' check(length(company_context)<=2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '180 days');
create table public.sp_roles(id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 3 and 120),job_description text not null check(length(job_description) between 12 and 5000),compensation text not null default '' check(length(compensation)<=180),criteria jsonb not null,pitch text not null default '' check(length(pitch)<=2000),state text not null default 'draft' check(state in ('draft','active','paused','closed')),brief_version integer not null default 1,internal_status text not null default 'not_searched',public_status text not null default 'not_searched',last_searched_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '180 days',unique(id,owner_id));
create table public.sp_role_candidates(id uuid primary key,role_id uuid not null,owner_id uuid not null,brief_version integer not null,source text not null check(source in ('internal','public')),reference text not null check(reference ~ '^SP-[A-F0-9]{16}$'),pipeline_stage text not null default 'new' check(pipeline_stage in ('new','saved','passed')),feedback text not null default '' check(length(feedback)<=1000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '180 days',foreign key(role_id,owner_id) references public.sp_roles(id,owner_id) on delete cascade,unique(role_id,brief_version,source,reference));
create table public.sp_public_discoveries(id uuid primary key,owner_id uuid not null,role_id uuid not null,brief_version integer not null,reference text not null,canonical_url text not null check(length(canonical_url)<=1000),person_name text not null check(length(person_name)<=180),reported_title text not null default '' check(length(reported_title)<=200),reported_company text not null default '' check(length(reported_company)<=200),source_excerpt text not null default '' check(length(source_excerpt)<=700),provider text not null default 'perplexity/sonar',sources jsonb not null default '[]',review_status text not null default 'pending' check(review_status in ('pending','approved','rejected')),approved_copy jsonb,approval_basis text,approval_evidence text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,approval_expires_at timestamptz,discovered_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '30 days',foreign key(role_id,owner_id) references public.sp_roles(id,owner_id) on delete cascade,unique(role_id,brief_version,canonical_url),unique(reference));
create table public.sp_introductions(id uuid primary key,owner_id uuid not null,role_id uuid not null,candidate_id uuid not null references public.sp_role_candidates(id) on delete cascade,reference text not null,status text not null default 'requested' check(status in ('requested','reviewing','candidate_agreed','introduced','declined')),request_note text not null default '' check(length(request_note)<=1500),permission_evidence text,operator_note text,updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '180 days',foreign key(role_id,owner_id) references public.sp_roles(id,owner_id) on delete cascade,unique(candidate_id));
create index on public.sp_roles(owner_id,created_at);
create index on public.sp_role_candidates(owner_id,role_id,brief_version);
create index on public.sp_public_discoveries(owner_id,role_id,brief_version);
create index on public.sp_public_discoveries(review_status,discovered_at);
create index on public.sp_introductions(owner_id,role_id);
alter table public.sp_employers enable row level security;
alter table public.sp_roles enable row level security;
alter table public.sp_role_candidates enable row level security;
alter table public.sp_public_discoveries enable row level security;
alter table public.sp_introductions enable row level security;
revoke all on public.sp_employers,public.sp_roles,public.sp_role_candidates,public.sp_public_discoveries,public.sp_introductions from anon,authenticated;
grant all on public.sp_employers,public.sp_roles,public.sp_role_candidates,public.sp_public_discoveries,public.sp_introductions to service_role;
